<?php require __DIR__.'/config/database.php';require __DIR__.'/v1_nav.php';$uid=(int)$pdo->query("SELECT id FROM users ORDER BY id LIMIT 1")->fetchColumn();$q=$pdo->prepare("SELECT us.*,GROUP_CONCAT(t.tag_code SEPARATOR ', ') tags FROM user_shoes us LEFT JOIN tags t ON t.user_shoe_id=us.id AND t.activation_status='ACTIVE' WHERE us.user_id=? AND us.active=1 GROUP BY us.id ORDER BY us.id DESC");$q->execute([$uid]);$rows=$q->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Shoes — TapSole</title><link rel="stylesheet" href="assets/v1.css"></head><body><main class="app"><div class="top"><div class="brand">TAPSOLE<i></i></div><a class="avatar" href="settings.php">G</a></div><div class="kicker">YOUR ROTATION</div><h1 class="pageTitle">Running shoes.</h1><?php foreach($rows as $s):$nm=$s['nickname']?:trim($s['custom_brand'].' '.$s['custom_model']);?><a class="shoeCard" href="shoe.php?id=<?=$s['id']?>"><div class="shoeCardTop"><div><div class="kicker"><?=htmlspecialchars($s['custom_brand'])?></div><h3><?=htmlspecialchars($nm)?></h3><span class="pill"><?=htmlspecialchars($s['tags']?:'NO NFC')?></span></div><div class="shoePic"><img class="shoe-outline" src="assets/sneaker.png" alt="Sneaker"></div></div></a><?php endforeach;?><a class="fab" href="tag_new.php">＋</a><?php v1nav('shoes');?></main></body></html>